package com.fab.wab.customer.app

import com.fab.wab.customer.BuildConfig
import com.fab.wab.customer.core.common.AppEnvironment
import com.fab.wab.customer.core.common.DataSource
import com.fab.wab.customer.core.common.MerchantLinks
import org.koin.dsl.module

/** Per-variant values (flavor dev/prod, build type debug/release) generated by Gradle into [BuildConfig]. */
internal val appEnvironmentModule = module {
    single {
        AppEnvironment(
            name = BuildConfig.ENVIRONMENT,
            apiBaseUrl = BuildConfig.API_BASE_URL,
            webBaseUrl = BuildConfig.WEB_BASE_URL,
            appVersion = BuildConfig.VERSION_NAME,
            appVersionCode = BuildConfig.VERSION_CODE,
            isDebug = BuildConfig.DEBUG,
            dataSource = DataSource.fromConfig(BuildConfig.DATA_SOURCE),
            merchant = MerchantLinks(BuildConfig.MERCHANT_REGISTER_URL, BuildConfig.MERCHANT_STORE_URL, BuildConfig.MERCHANT_APP_ID),
        )
    }
}
